// The Case ID users see: <FACILITY>-<D|M>-<YEAR>-<NNNNN> (from the file or generated by
// the system — backend services/caseIds.js). Older records without one fall back to the
// internal case number, which stays the hidden link key. Patient # is not shown.
export const caseIdOf = (r) => (r ? (r.source_case_id || r.case_no || null) : null);
